1	/**
2	 * galois.mjs — arithmetic in the finite field GF(2^8) used by AES.
3	 *
4	 * The Python original (`pyaes`) ships pre-computed S-box / multiplication
5	 * tables. This port reproduces the *values* of those tables by deriving them
6	 * from first principles (FIPS-197 §4), so the only thing hard-coded anywhere in
7	 * the AES core is the field's reduction polynomial. Nothing here touches
8	 * `node:crypto`; every operation is plain integer bit math on bytes.
9	 *
10	 * Field: GF(2) polynomials modulo the irreducible AES polynomial
11	 *   m(x) = x^8 + x^4 + x^3 + x + 1   (0x11b)
12	 *
13	 * Bytes are ordinary JS numbers in the range 0..255.
14	 */
15	
16	/** The AES reduction polynomial, minus its x^8 term (FIPS-197 §4.2). */
17	const REDUCTION = 0x1b;
18	
19	/**
20	 * Multiply a byte by x (i.e. by 0x02) in GF(2^8).
21	 *
22	 * A left shift is the polynomial multiplication; if the shift pushed a bit out
23	 * of the x^7 position the result is reduced modulo m(x) by XORing 0x1b.
24	 *
25	 * @param {number} a byte, 0..255
26	 * @returns {number} byte, 0..255
27	 */
28	export function xtime(a) {
29	  const b = (a & 0xff) << 1;
30	  return (b & 0x100 ? b ^ REDUCTION : b) & 0xff;
31	}
32	
33	/**
34	 * Multiply two bytes in GF(2^8) (russian-peasant / shift-and-add).
35	 *
36	 * Runs in constant iteration count (8) so it stays trivially auditable; it is
37	 * only ever used at module-load time to build the lookup tables.
38	 *
39	 * @param {number} a byte, 0..255
40	 * @param {number} b byte, 0..255
41	 * @returns {number} byte, 0..255
42	 */
43	export function gmul(a, b) {
44	  let x = a & 0xff;
45	  let y = b & 0xff;
46	  let product = 0;
47	  for (let i = 0; i < 8; i += 1) {
48	    if (y & 1) product ^= x;
49	    y >>= 1;
50	    x = xtime(x);
51	  }
52	  return product & 0xff;
53	}
54	
55	/**
56	 * Multiplicative inverse in GF(2^8).
57	 *
58	 * Zero has no inverse; AES defines the S-box so that 0x00 maps to itself, so we
59	 * follow that convention and return 0 for 0 (FIPS-197 §5.1.1).
60	 *
61	 * The table is built once at module load by exhaustive search over the 255
62	 * non-zero field elements — small, deterministic, and free of any dependency on
63	 * a hard-coded inverse table.
64	 *
65	 * @param {number} a byte, 0..255
66	 * @returns {number} byte, 0..255
67	 */
68	export function ginv(a) {
69	  return INVERSES[a & 0xff];
70	}
71	
72	/** Lazily-free precomputation: 256-entry inverse table, index 0 fixed at 0. */
73	const INVERSES = (() => {
74	  const table = new Uint8Array(256);
75	  for (let a = 1; a < 256; a += 1) {
76	    if (table[a] !== 0) continue; // already filled in as some earlier pair
77	    for (let b = 1; b < 256; b += 1) {
78	      if (gmul(a, b) === 1) {
79	        table[a] = b;
80	        table[b] = a; // inversion is an involution
81	        break;
82	      }
83	    }
84	  }
85	  return table;
86	})();
87

1	/**
2	 * tables.mjs — the AES substitution boxes, round constants and MixColumns
3	 * multiplication tables, all derived at module load.
4	 *
5	 * `pyaes` carries these as literal Python lists. Reproducing the literals by
6	 * hand would be unverifiable, so instead the S-box is *computed* exactly as
7	 * FIPS-197 §5.1.1 defines it — multiplicative inverse in GF(2^8) followed by the
8	 * affine transform — and then checked against known FIPS-197 values. If the
9	 * derivation is ever wrong the module refuses to load rather than silently
10	 * producing wrong ciphertext.
11	 */
12	
13	import { gmul, ginv, xtime } from './galois.mjs';
14	
15	/**
16	 * Rotate a byte left by `n` bits (the `b_i xor b_(i+4) xor ...` shifts in the
17	 * S-box affine transform are byte rotations).
18	 *
19	 * @param {number} b byte, 0..255
20	 * @param {number} n bit count, 1..7
21	 * @returns {number} byte, 0..255
22	 */
23	function rotl8(b, n) {
24	  return ((b << n) | (b >>> (8 - n))) & 0xff;
25	}
26	
27	/**
28	 * The AES S-box: y = affine(inv(x)).
29	 *
30	 * affine(b) = b ^ rotl(b,1) ^ rotl(b,2) ^ rotl(b,3) ^ rotl(b,4) ^ 0x63
31	 *
32	 * @type {Uint8Array}
33	 */
34	export const SBOX = (() => {
35	  const box = new Uint8Array(256);
36	  for (let x = 0; x < 256; x += 1) {
37	    const b = ginv(x);
38	    box[x] = (b ^ rotl8(b, 1) ^ rotl8(b, 2) ^ rotl8(b, 3) ^ rotl8(b, 4) ^ 0x63) & 0xff;
39	  }
40	  return box;
41	})();
42	
43	/**
44	 * The inverse S-box, obtained by inverting the permutation above.
45	 * @type {Uint8Array}
46	 */
47	export const INV_SBOX = (() => {
48	  const box = new Uint8Array(256);
49	  for (let x = 0; x < 256; x += 1) box[SBOX[x]] = x;
50	  return box;
51	})();
52	
53	/**
54	 * Round constants. `RCON[i]` (for i >= 1) is x^(i-1) in GF(2^8):
55	 * 01 02 04 08 10 20 40 80 1b 36. Index 0 is unused padding so that the array is
56	 * indexed by round number, matching FIPS-197's notation.
57	 * @type {Uint8Array}
58	 */
59	export const RCON = (() => {
60	  const rcon = new Uint8Array(11);
61	  let value = 0x01;
62	  for (let i = 1; i < 11; i += 1) {
63	    rcon[i] = value;
64	    value = xtime(value);
65	  }
66	  return rcon;
67	})();
68	
69	/**
70	 * Build a 256-entry table of `byte -> gmul(byte, factor)`.
71	 * @param {number} factor
72	 * @returns {Uint8Array}
73	 */
74	function mulTable(factor) {
75	  const table = new Uint8Array(256);
76	  for (let x = 0; x < 256; x += 1) table[x] = gmul(x, factor);
77	  return table;
78	}
79	
80	/** Multiply-by-2 table (MixColumns). @type {Uint8Array} */
81	export const MUL2 = mulTable(0x02);
82	/** Multiply-by-3 table (MixColumns). @type {Uint8Array} */
83	export const MUL3 = mulTable(0x03);
84	/** Multiply-by-9 table (InvMixColumns). @type {Uint8Array} */
85	export const MUL9 = mulTable(0x09);
86	/** Multiply-by-0x0b table (InvMixColumns). @type {Uint8Array} */
87	export const MUL11 = mulTable(0x0b);
88	/** Multiply-by-0x0d table (InvMixColumns). @type {Uint8Array} */
89	export const MUL13 = mulTable(0x0d);
90	/** Multiply-by-0x0e table (InvMixColumns). @type {Uint8Array} */
91	export const MUL14 = mulTable(0x0e);
92	
93	// ---------------------------------------------------------------------------
94	// Self-verification. These run once, at import time; a failure means the field
95	// arithmetic or the affine transform is broken and no ciphertext produced by
96	// this library could be trusted.
97	// ---------------------------------------------------------------------------
98	
99	/**
100	 * @param {boolean} condition
101	 * @param {string} message
102	 */
103	function check(condition, message) {
104	  if (!condition) throw new Error(`AES table derivation failed: ${message}`);
105	}
106	
107	/** Spot values taken from the FIPS-197 §5.1.1 S-box figure. */
108	const SBOX_KNOWN = [
109	  [0x00, 0x63],
110	  [0x01, 0x7c],
111	  [0x10, 0xca],
112	  [0x53, 0xed],
113	  [0x7f, 0xd2],
114	  [0xff, 0x16],
115	];
116	
117	for (const [input, expected] of SBOX_KNOWN) {
118	  check(
119	    SBOX[input] === expected,
120	    `SBOX[0x${input.toString(16).padStart(2, '0')}] === 0x${SBOX[input]
121	      .toString(16)
122	      .padStart(2, '0')}, expected 0x${expected.toString(16).padStart(2, '0')}`,
123	  );
124	}
125	
126	for (let i = 0; i < 256; i += 1) {
127	  check(INV_SBOX[SBOX[i]] === i, `INV_SBOX is not the inverse of SBOX at index ${i}`);
128	}
129	
130	check(
131	  RCON[1] === 0x01 && RCON[8] === 0x80 && RCON[9] === 0x1b && RCON[10] === 0x36,
132	  'RCON does not match 01 02 04 08 10 20 40 80 1b 36',
133	);
134

1	/**
2	 * errors.mjs — error types raised by the AES core.
3	 *
4	 * The Python original raises bare `ValueError`s from inside `pyaes`
5	 * (`ValueError: Invalid key size`, `ValueError: plaintext block must be
6	 * 16 bytes`). This layer stays deliberately Python-agnostic: it knows nothing
7	 * about tracebacks, exit codes or `repr()`. The pyaes shim sitting above it is
8	 * responsible for translating these classes into the exact CPython-style
9	 * diagnostics, so the cipher core remains a clean, reusable library.
10	 */
11	
12	/**
13	 * Raised when a key is not 16, 24 or 32 bytes long.
14	 *
15	 * The default message matches the text the Python side ultimately reports, but
16	 * callers may override it.
17	 */
18	export class InvalidKeySizeError extends Error {
19	  /** @param {string} [message] */
20	  constructor(message = 'Invalid key size') {
21	    super(message);
22	    this.name = 'InvalidKeySizeError';
23	  }
24	}
25	
26	/**
27	 * Raised when a block handed to the cipher is not exactly `BLOCK_SIZE` bytes.
28	 *
29	 * The message is always supplied by the caller, because the wording differs by
30	 * direction upstream (plaintext vs. ciphertext block).
31	 */
32	export class InvalidBlockSizeError extends Error {
33	  /** @param {string} message */
34	  constructor(message) {
35	    super(message);
36	    this.name = 'InvalidBlockSizeError';
37	  }
38	}
39

1	/**
2	 * key-schedule.mjs — the AES key expansion (FIPS-197 §5.2).
3	 *
4	 * Mirrors what `pyaes.AES.__init__` does when it is handed a key: reject
5	 * anything that is not 16/24/32 bytes (`ValueError: Invalid key size` upstream),
6	 * otherwise expand the key into `rounds + 1` round keys.
7	 *
8	 * Byte order note: `pyaes` keeps its round keys as 32-bit words and transposes
9	 * during AddRoundKey. Here each round key is flattened into a Uint8Array(16)
10	 * whose byte order is identical to the 16-byte input block, so AddRoundKey is a
11	 * plain 16-way XOR with no transposition anywhere in the hot path.
12	 */
13	
14	import { SBOX, RCON } from './tables.mjs';
15	import { InvalidKeySizeError } from './errors.mjs';
16	
17	/** AES block size in bytes. Always 16 — Rijndael's larger blocks are not AES. */
18	export const BLOCK_SIZE = 16;
19	
20	/**
21	 * Number of rounds per key length in bytes (FIPS-197 Fig. 4).
22	 * @type {Map<number, number>}
23	 */
24	export const ROUNDS_BY_KEY_SIZE = new Map([
25	  [16, 10],
26	  [24, 12],
27	  [32, 14],
28	]);
29	
30	/**
31	 * True when `byteLength` is a key size AES accepts.
32	 * @param {number} byteLength
33	 * @returns {boolean}
34	 */
35	export function isValidKeySize(byteLength) {
36	  return ROUNDS_BY_KEY_SIZE.has(byteLength);
37	}
38	
39	/**
40	 * Apply the S-box to each byte of a 4-byte word, in place.
41	 * @param {Uint8Array} word
42	 */
43	function subWord(word) {
44	  word[0] = SBOX[word[0]];
45	  word[1] = SBOX[word[1]];
46	  word[2] = SBOX[word[2]];
47	  word[3] = SBOX[word[3]];
48	}
49	
50	/**
51	 * Rotate a 4-byte word one byte left: [a0,a1,a2,a3] -> [a1,a2,a3,a0].
52	 * @param {Uint8Array} word
53	 */
54	function rotWord(word) {
55	  const first = word[0];
56	  word[0] = word[1];
57	  word[1] = word[2];
58	  word[2] = word[3];
59	  word[3] = first;
60	}
61	
62	/**
63	 * Expand a cipher key into the AES round keys.
64	 *
65	 * @param {Uint8Array} keyBytes 16, 24 or 32 bytes
66	 * @returns {{ keySize: number, rounds: number, roundKeys: Uint8Array[] }}
67	 *   `roundKeys` has `rounds + 1` entries, each a fresh Uint8Array(16) in input
68	 *   block byte order.
69	 * @throws {InvalidKeySizeError} when the key length is not 16/24/32
70	 */
71	export function expandKey(keyBytes) {
72	  const keySize = keyBytes == null ? -1 : keyBytes.length;
73	  if (!isValidKeySize(keySize)) throw new InvalidKeySizeError();
74	
75	  const rounds = /** @type {number} */ (ROUNDS_BY_KEY_SIZE.get(keySize));
76	  const nk = keySize / 4; // key length in 32-bit words: 4, 6 or 8
77	  const totalWords = 4 * (rounds + 1); // 44, 52 or 60
78	
79	  // words[i] is w_i from FIPS-197, stored big-endian as 4 bytes.
80	  /** @type {Uint8Array[]} */
81	  const words = new Array(totalWords);
82	
83	  for (let i = 0; i < nk; i += 1) {
84	    words[i] = Uint8Array.prototype.slice.call(keyBytes, i * 4, i * 4 + 4);
85	  }
86	
87	  for (let i = nk; i < totalWords; i += 1) {
88	    const temp = words[i - 1].slice();
89	    if (i % nk === 0) {
90	      rotWord(temp);
91	      subWord(temp);
92	      temp[0] ^= RCON[i / nk];
93	    } else if (nk > 6 && i % nk === 4) {
94	      // AES-256 only: an extra SubWord halfway through each key block.
95	      subWord(temp);
96	    }
97	    const prev = words[i - nk];
98	    const word = new Uint8Array(4);
99	    word[0] = prev[0] ^ temp[0];
100	    word[1] = prev[1] ^ temp[1];
101	    word[2] = prev[2] ^ temp[2];
102	    word[3] = prev[3] ^ temp[3];
103	    words[i] = word;
104	  }
105	
106	  // Flatten groups of four words into block-ordered 16-byte round keys.
107	  /** @type {Uint8Array[]} */
108	  const roundKeys = new Array(rounds + 1);
109	  for (let r = 0; r <= rounds; r += 1) {
110	    const roundKey = new Uint8Array(BLOCK_SIZE);
111	    for (let w = 0; w < 4; w += 1) roundKey.set(words[r * 4 + w], w * 4);
112	    roundKeys[r] = roundKey;
113	  }
114	
115	  return { keySize, rounds, roundKeys };
116	}
