/**
 * block-cipher.mjs — the raw AES block cipher (FIPS-197 §5.1 and §5.3).
 *
 * This is the Node equivalent of `pyaes.AES`: a single-block, key-only
 * primitive with no mode of operation, no padding and no I/O. The Python class
 * exposes `encrypt(plaintext)` / `decrypt(ciphertext)` over 16-byte lists; here
 * the same two operations take and return `Uint8Array(16)`.
 *
 * Differences from `pyaes` that are deliberate and behaviour-preserving:
 *
 *  - `pyaes` keeps the state as four 32-bit words and transposes on every
 *    AddRoundKey. This port keeps the state as a flat 16-byte array in the same
 *    order as the input block (column-major, `state[row + 4*col]`), so
 *    AddRoundKey is a plain 16-way XOR. The round keys produced by
 *    `key-schedule.mjs` are pre-flattened to match.
 *  - The straightforward inverse cipher is used (InvShiftRows / InvSubBytes /
 *    AddRoundKey / InvMixColumns), not the equivalent inverse cipher, so no
 *    separate decryption key schedule is needed.
 *
 * Byte-for-byte identical ciphertext to the Python original; only the internal
 * data layout differs.
 */

import { SBOX, INV_SBOX, MUL2, MUL3, MUL9, MUL11, MUL13, MUL14 } from './tables.mjs';
import { BLOCK_SIZE, expandKey } from './key-schedule.mjs';

export { BLOCK_SIZE };

/**
 * XOR a 16-byte round key into the state, in place (FIPS-197 §5.1.4).
 *
 * @param {Uint8Array} state 16 bytes, mutated
 * @param {Uint8Array} roundKey 16 bytes
 */
function addRoundKey(state, roundKey) {
  for (let i = 0; i < BLOCK_SIZE; i += 1) state[i] ^= roundKey[i];
}

/**
 * Replace every byte of the state with `SBOX[byte]` (FIPS-197 §5.1.1).
 * @param {Uint8Array} state 16 bytes, mutated
 */
function subBytes(state) {
  for (let i = 0; i < BLOCK_SIZE; i += 1) state[i] = SBOX[state[i]];
}

/**
 * Replace every byte of the state with `INV_SBOX[byte]` (FIPS-197 §5.3.2).
 * @param {Uint8Array} state 16 bytes, mutated
 */
function invSubBytes(state) {
  for (let i = 0; i < BLOCK_SIZE; i += 1) state[i] = INV_SBOX[state[i]];
}

/**
 * ShiftRows: cyclically shift row `r` of the state left by `r` bytes
 * (FIPS-197 §5.1.2). In the flat column-major layout, row `r` lives at indices
 * r, r+4, r+8, r+12.
 *
 * @param {Uint8Array} s 16 bytes, mutated
 */
function shiftRows(s) {
  // Row 0 is unchanged.
  let t = s[1];
  s[1] = s[5];
  s[5] = s[9];
  s[9] = s[13];
  s[13] = t;

  t = s[2];
  s[2] = s[10];
  s[10] = t;
  t = s[6];
  s[6] = s[14];
  s[14] = t;

  t = s[15];
  s[15] = s[11];
  s[11] = s[7];
  s[7] = s[3];
  s[3] = t;
}

/**
 * InvShiftRows: cyclically shift row `r` right by `r` bytes (FIPS-197 §5.3.1).
 * @param {Uint8Array} s 16 bytes, mutated
 */
function invShiftRows(s) {
  // Row 0 is unchanged.
  let t = s[13];
  s[13] = s[9];
  s[9] = s[5];
  s[5] = s[1];
  s[1] = t;

  // Row 2 shifts by two either way, so it is its own inverse.
  t = s[2];
  s[2] = s[10];
  s[10] = t;
  t = s[6];
  s[6] = s[14];
  s[14] = t;

  t = s[3];
  s[3] = s[7];
  s[7] = s[11];
  s[11] = s[15];
  s[15] = t;
}

/**
 * MixColumns: treat each 4-byte column as a polynomial and multiply it by
 * {03}x^3 + {01}x^2 + {01}x + {02} in GF(2^8) (FIPS-197 §5.1.3).
 *
 * @param {Uint8Array} s 16 bytes, mutated
 */
function mixColumns(s) {
  for (let c = 0; c < BLOCK_SIZE; c += 4) {
    const a0 = s[c];
    const a1 = s[c + 1];
    const a2 = s[c + 2];
    const a3 = s[c + 3];
    s[c] = MUL2[a0] ^ MUL3[a1] ^ a2 ^ a3;
    s[c + 1] = a0 ^ MUL2[a1] ^ MUL3[a2] ^ a3;
    s[c + 2] = a0 ^ a1 ^ MUL2[a2] ^ MUL3[a3];
    s[c + 3] = MUL3[a0] ^ a1 ^ a2 ^ MUL2[a3];
  }
}

/**
 * InvMixColumns: multiply each column by the inverse polynomial
 * {0b}x^3 + {0d}x^2 + {09}x + {0e} (FIPS-197 §5.3.3).
 *
 * @param {Uint8Array} s 16 bytes, mutated
 */
function invMixColumns(s) {
  for (let c = 0; c < BLOCK_SIZE; c += 4) {
    const a0 = s[c];
    const a1 = s[c + 1];
    const a2 = s[c + 2];
    const a3 = s[c + 3];
    s[c] = MUL14[a0] ^ MUL11[a1] ^ MUL13[a2] ^ MUL9[a3];
    s[c + 1] = MUL9[a0] ^ MUL14[a1] ^ MUL11[a2] ^ MUL13[a3];
    s[c + 2] = MUL13[a0] ^ MUL9[a1] ^ MUL14[a2] ^ MUL11[a3];
    s[c + 3] = MUL11[a0] ^ MUL13[a1] ^ MUL9[a2] ^ MUL14[a3];
  }
}

/**
 * Defensive internal guard. The pyaes shim above this layer is what produces the
 * Python-visible `ValueError: plaintext block must be 16 bytes`, so reaching
 * this check means a caller inside the port has a bug.
 *
 * @param {Uint8Array} block
 * @param {string} label
 */
function requireBlock(block, label) {
  if (block == null || block.length !== BLOCK_SIZE) {
    const got = block == null ? 'null' : String(block.length);
    throw new TypeError(`AES ${label} must be exactly ${BLOCK_SIZE} bytes (got ${got})`);
  }
}

/**
 * A keyed AES block cipher instance.
 *
 * The key schedule is computed once in the constructor and reused, which is what
 * makes repeated single-block calls cheap — the same trade-off `pyaes` makes.
 */
export class AES {
  /**
   * @param {Uint8Array} keyBytes 16, 24 or 32 bytes
   * @throws {import('./errors.mjs').InvalidKeySizeError} for any other length
   */
  constructor(keyBytes) {
    const { keySize, rounds, roundKeys } = expandKey(keyBytes);
    /** @type {number} */
    this._keySize = keySize;
    /** @type {number} */
    this._rounds = rounds;
    /** @type {Uint8Array[]} */
    this._roundKeys = roundKeys;
  }

  /** Key length in bytes: 16, 24 or 32. @returns {number} */
  get keySize() {
    return this._keySize;
  }

  /** Number of cipher rounds: 10, 12 or 14. @returns {number} */
  get rounds() {
    return this._rounds;
  }

  /**
   * Encrypt one 16-byte block.
   *
   * AddRoundKey, then (rounds - 1) full rounds, then a final round with no
   * MixColumns (FIPS-197 §5.1). The input is copied, never mutated.
   *
   * @param {Uint8Array} block 16 bytes
   * @returns {Uint8Array} a fresh 16-byte block
   * @throws {TypeError} when `block.length !== 16`
   */
  encryptBlock(block) {
    requireBlock(block, 'plaintext block');

    const state = new Uint8Array(BLOCK_SIZE);
    state.set(block);
    const roundKeys = this._roundKeys;
    const rounds = this._rounds;

    addRoundKey(state, roundKeys[0]);
    for (let round = 1; round < rounds; round += 1) {
      subBytes(state);
      shiftRows(state);
      mixColumns(state);
      addRoundKey(state, roundKeys[round]);
    }
    subBytes(state);
    shiftRows(state);
    addRoundKey(state, roundKeys[rounds]);

    return state;
  }

  /**
   * Decrypt one 16-byte block, using the straightforward inverse cipher
   * (FIPS-197 §5.3). The input is copied, never mutated.
   *
   * @param {Uint8Array} block 16 bytes
   * @returns {Uint8Array} a fresh 16-byte block
   * @throws {TypeError} when `block.length !== 16`
   */
  decryptBlock(block) {
    requireBlock(block, 'ciphertext block');

    const state = new Uint8Array(BLOCK_SIZE);
    state.set(block);
    const roundKeys = this._roundKeys;
    const rounds = this._rounds;

    addRoundKey(state, roundKeys[rounds]);
    for (let round = rounds - 1; round >= 1; round -= 1) {
      invShiftRows(state);
      invSubBytes(state);
      addRoundKey(state, roundKeys[round]);
      invMixColumns(state);
    }
    invShiftRows(state);
    invSubBytes(state);
    addRoundKey(state, roundKeys[0]);

    return state;
  }
}

/**
 * index.mjs — public surface of the hand-written AES core.
 *
 * This is the only module the rest of the port needs to import; it stands in for
 * the parts of the `pyaes` package the Python original touches (`pyaes.AES` and
 * its key-size validation). Nothing here knows about ECB, argparse, `repr()` or
 * Python tracebacks — those live in the shim layers above.
 */

export { AES, BLOCK_SIZE } from './block-cipher.mjs';
export { expandKey, isValidKeySize, ROUNDS_BY_KEY_SIZE } from './key-schedule.mjs';
export { InvalidKeySizeError, InvalidBlockSizeError } from './errors.mjs';

/**
 * Scratch KAT harness for /output/lib/aes — NOT a deliverable.
 * FIPS-197 Appendix B/C vectors + round-trip fuzz + interface/contract checks.
 */

import {
  AES,
  BLOCK_SIZE,
  expandKey,
  isValidKeySize,
  ROUNDS_BY_KEY_SIZE,
  InvalidKeySizeError,
  InvalidBlockSizeError,
} from '/output/lib/aes/index.mjs';
import { xtime, gmul, ginv } from '/output/lib/aes/galois.mjs';
import { SBOX, INV_SBOX, RCON, MUL2, MUL3, MUL9, MUL11, MUL13, MUL14 } from '/output/lib/aes/tables.mjs';

let pass = 0;
let fail = 0;

function ok(name, cond, extra = '') {
  if (cond) {
    pass += 1;
    console.log(`PASS  ${name}`);
  } else {
    fail += 1;
    console.log(`FAIL  ${name}${extra ? ' :: ' + extra : ''}`);
  }
}

const hex = (u8) => Buffer.from(u8).toString('hex');
const unhex = (s) => new Uint8Array(Buffer.from(s, 'hex'));
const seq = (n) => Uint8Array.from({ length: n }, (_, i) => i);

// --- FIPS-197 Appendix C ------------------------------------------------------
const PT_C = '00112233445566778899aabbccddeeff';
const APPENDIX_C = [
  ['AES-128 C.1', seq(16), PT_C, '69c4e0d86a7b0430d8cdb78070b4c55a'],
  ['AES-192 C.2', seq(24), PT_C, 'dda97ca4864cdfe06eaf70a0ec0d7191'],
  ['AES-256 C.3', seq(32), PT_C, '8ea2b7ca516745bfeafc49904b496089'],
];
// --- FIPS-197 Appendix B -----------------------------------------------------
const APPENDIX_B = [
  [
    'AES-128 Appendix B',
    unhex('2b7e151628aed2a6abf7158809cf4f3c'),
    '3243f6a8885a308d313198a2e0370734',
    '3925841d02dc09fbdc118597196a0b32',
  ],
];

for (const [name, key, ptHex, ctHex] of [...APPENDIX_C, ...APPENDIX_B]) {
  const aes = new AES(key);
  const pt = unhex(ptHex);
  const ptCopy = pt.slice();
  const ct = aes.encryptBlock(pt);
  ok(`${name} encrypt`, hex(ct) === ctHex, `got ${hex(ct)} want ${ctHex}`);
  ok(`${name} input not mutated`, hex(pt) === hex(ptCopy));
  const ctCopy = ct.slice();
  const back = aes.decryptBlock(ct);
  ok(`${name} decrypt`, hex(back) === ptHex, `got ${hex(back)} want ${ptHex}`);
  ok(`${name} ciphertext not mutated by decrypt`, hex(ct) === hex(ctCopy));
  ok(`${name} keySize/rounds`, aes.keySize === key.length && aes.rounds === ROUNDS_BY_KEY_SIZE.get(key.length));
  ok(`${name} returns fresh Uint8Array`, ct instanceof Uint8Array && ct !== pt && back !== ct);
}

// --- SPEC.md §3 reference vectors (ASCII keys/data) --------------------------
const enc = (s) => new Uint8Array(Buffer.from(s, 'utf8'));
const SPEC_VECTORS = [
  ['0123456789012345', '0123456789012345', '5f7df0bf103a8c4ae6faad9906ac3b2a'],
  ['012345678901234567890123', '0123456789012345', '2d764567 3e4259de72ee5c2a754a67'.replace(/ /g, '')],
  ['01234567890123456789012345678901', '0123456789012345', '5d998144e94f14465b7d39f43cf18a57'],
];
for (const [key, data, ctHex] of SPEC_VECTORS) {
  const got = hex(new AES(enc(key)).encryptBlock(enc(data)));
  ok(`SPEC vector key=${key.length}B`, got === ctHex, `got ${got} want ${ctHex}`);
}
// cross-key decrypt from SPEC row 2 / row 3 (line 2 of program output)
const k2 = enc('0123456789012345');
ok(
  'SPEC cross-decrypt 192->128',
  hex(new AES(k2).decryptBlock(unhex('2d7645673e4259de72ee5c2a754a67'.padStart(32, '0')))) !== '',
);
ok(
  'SPEC cross-decrypt row2 line2',
  hex(new AES(k2).decryptBlock(unhex(SPEC_VECTORS[1][2]))) === '2a39c681c5798f0dff24b2b540012897',
  hex(new AES(k2).decryptBlock(unhex(SPEC_VECTORS[1][2]))),
);
ok(
  'SPEC cross-decrypt row3 line2',
  hex(new AES(k2).decryptBlock(unhex(SPEC_VECTORS[2][2]))) === '2352d9c5a30f9f203225e7137e5210f2',
  hex(new AES(k2).decryptBlock(unhex(SPEC_VECTORS[2][2]))),
);

// --- harness vectors.json (if it has raw AES material) ----------------------
// (informational only; skipped silently if the shape does not match)

// --- round-trip fuzz ---------------------------------------------------------
let rtFail = 0;
let rtCount = 0;
for (const keySize of [16, 24, 32]) {
  for (let trial = 0; trial < 2000; trial += 1) {
    const key = new Uint8Array(keySize);
    const block = new Uint8Array(16);
    for (let i = 0; i < keySize; i += 1) key[i] = (Math.random() * 256) | 0;
    for (let i = 0; i < 16; i += 1) block[i] = (Math.random() * 256) | 0;
    const aes = new AES(key);
    const ct = aes.encryptBlock(block);
    const back = aes.decryptBlock(ct);
    rtCount += 1;
    if (hex(back) !== hex(block)) rtFail += 1;
    if (hex(ct) === hex(block)) rtFail += 1; // sanity: not a no-op
  }
}
ok(`round-trip fuzz (${rtCount} blocks, 3 key sizes)`, rtFail === 0, `${rtFail} mismatches`);

// --- galois / tables ---------------------------------------------------------
ok('xtime(0x57)=0xae', xtime(0x57) === 0xae);
ok('xtime(0x80)=0x1b', xtime(0x80) === 0x1b);
ok('gmul(0x57,0x13)=0xfe (FIPS-197 4.2 example)', gmul(0x57, 0x13) === 0xfe);
ok('gmul(0x57,0x83)=0xc1 (FIPS-197 4.2 example)', gmul(0x57, 0x83) === 0xc1);
ok('ginv(0)=0', ginv(0) === 0);
let ginvBad = 0;
for (let a = 1; a < 256; a += 1) if (gmul(a, ginv(a)) !== 1) ginvBad += 1;
ok('ginv is a true inverse for all 255 nonzero bytes', ginvBad === 0, `${ginvBad} bad`);
ok(
  'SBOX spot values',
  SBOX[0x00] === 0x63 && SBOX[0x01] === 0x7c && SBOX[0x10] === 0xca && SBOX[0x53] === 0xed && SBOX[0x7f] === 0xd2 && SBOX[0xff] === 0x16,
);
let sboxPerm = new Set(SBOX).size;
ok('SBOX is a permutation of 0..255', sboxPerm === 256, `${sboxPerm} distinct`);
let invBad = 0;
for (let i = 0; i < 256; i += 1) if (INV_SBOX[SBOX[i]] !== i) invBad += 1;
ok('INV_SBOX inverts SBOX', invBad === 0);
ok(
  'RCON = 00 01 02 04 08 10 20 40 80 1b 36',
  hex(RCON) === '000102040810204080' + '1b36',
  hex(RCON),
);
ok('RCON is Uint8Array(11)', RCON instanceof Uint8Array && RCON.length === 11);
let mulBad = 0;
for (let i = 0; i < 256; i += 1) {
  if (MUL2[i] !== gmul(i, 2)) mulBad += 1;
  if (MUL3[i] !== gmul(i, 3)) mulBad += 1;
  if (MUL9[i] !== gmul(i, 9)) mulBad += 1;
  if (MUL11[i] !== gmul(i, 0x0b)) mulBad += 1;
  if (MUL13[i] !== gmul(i, 0x0d)) mulBad += 1;
  if (MUL14[i] !== gmul(i, 0x0e)) mulBad += 1;
}
ok('MUL* tables match gmul', mulBad === 0, `${mulBad} bad`);

// --- key schedule ------------------------------------------------------------
// FIPS-197 Appendix A.1 last words for key 2b7e...4f3c: w43 = b6630ca6
const ks128 = expandKey(unhex('2b7e151628aed2a6abf7158809cf4f3c'));
ok('expandKey 128: 11 round keys', ks128.roundKeys.length === 11 && ks128.rounds === 10);
ok('expandKey 128: rk0 == key', hex(ks128.roundKeys[0]) === '2b7e151628aed2a6abf7158809cf4f3c');
ok(
  'expandKey 128: last round key (A.1 w40..w43)',
  hex(ks128.roundKeys[10]) === 'd014f9a8c9ee2589e13f0cc8b6630ca6',
  hex(ks128.roundKeys[10]),
);
// A.2 (192): w51 = 01002202
const ks192 = expandKey(unhex('8e73b0f7da0e6452c810f32b809079e562f8ead2522c6b7b'));
ok(
  'expandKey 192: last round key (A.2 w48..w51)',
  hex(ks192.roundKeys[12]) === 'e98ba06f448c773c8ecc720401002202',
  hex(ks192.roundKeys[12]),
);
// A.3 (256): w59 = 706c631e
const ks256 = expandKey(unhex('603deb1015ca71be2b73aef0857d77811f352c073b6108d72d9810a30914dff4'));
ok(
  'expandKey 256: last round key (A.3 w56..w59)',
  hex(ks256.roundKeys[14]) === 'fe4890d1e6188d0b046df344706c631e',
  hex(ks256.roundKeys[14]),
);
ok('expandKey rounds map', ks192.rounds === 12 && ks256.rounds === 14);
ok('roundKeys are 16-byte Uint8Arrays', ks256.roundKeys.every((k) => k instanceof Uint8Array && k.length === 16));
ok('round keys are distinct objects', new Set(ks256.roundKeys).size === 15);

ok('BLOCK_SIZE === 16', BLOCK_SIZE === 16);
ok('isValidKeySize', isValidKeySize(16) && isValidKeySize(24) && isValidKeySize(32) && !isValidKeySize(0) && !isValidKeySize(15) && !isValidKeySize(31) && !isValidKeySize(64));
ok('ROUNDS_BY_KEY_SIZE is a Map 16/24/32', ROUNDS_BY_KEY_SIZE instanceof Map && ROUNDS_BY_KEY_SIZE.get(16) === 10 && ROUNDS_BY_KEY_SIZE.get(24) === 12 && ROUNDS_BY_KEY_SIZE.get(32) === 14);

// --- error behaviour ---------------------------------------------------------
for (const bad of [0, 1, 8, 15, 17, 23, 25, 31, 33, 48]) {
  let e = null;
  try {
    new AES(new Uint8Array(bad));
  } catch (err) {
    e = err;
  }
  ok(
    `key length ${bad} -> InvalidKeySizeError`,
    e instanceof InvalidKeySizeError && e instanceof Error && e.message === 'Invalid key size',
    e && e.message,
  );
}
{
  let e = null;
  try {
    expandKey(new Uint8Array(7));
  } catch (err) {
    e = err;
  }
  ok('expandKey bad length throws InvalidKeySizeError', e instanceof InvalidKeySizeError);
}
{
  const ibs = new InvalidBlockSizeError('plaintext block must be 16 bytes');
  ok('InvalidBlockSizeError carries caller message', ibs instanceof Error && ibs.message === 'plaintext block must be 16 bytes');
}
const aes128 = new AES(seq(16));
for (const bad of [0, 1, 15, 17, 32]) {
  let eEnc = null;
  let eDec = null;
  try {
    aes128.encryptBlock(new Uint8Array(bad));
  } catch (err) {
    eEnc = err;
  }
  try {
    aes128.decryptBlock(new Uint8Array(bad));
  } catch (err) {
    eDec = err;
  }
  ok(`block length ${bad} -> TypeError both directions`, eEnc instanceof TypeError && eDec instanceof TypeError);
}

// --- ESM / dependency hygiene ------------------------------------------------
import { readdirSync, readFileSync } from 'node:fs';
const dir = '/output/lib/aes';
const files = readdirSync(dir).sort();
ok('exactly the six expected .mjs files', files.join(',') === 'block-cipher.mjs,errors.mjs,galois.mjs,index.mjs,key-schedule.mjs,tables.mjs', files.join(','));
let hygiene = [];
for (const f of files) {
  const src = readFileSync(`${dir}/${f}`, 'utf8');
  if (/\brequire\s*\(/.test(src)) hygiene.push(`${f}: require()`);
  if (/module\.exports/.test(src)) hygiene.push(`${f}: module.exports`);
  if (/__dirname/.test(src)) hygiene.push(`${f}: __dirname`);
  if (/crypto/i.test(src)) hygiene.push(`${f}: crypto mention`);
  if (/toSorted|Object\.groupBy|findLast/.test(src)) hygiene.push(`${f}: Node18-unsafe API`);
  for (const m of src.matchAll(/from\s+'([^']+)'/g)) {
    const spec = m[1];
    if (spec.startsWith('.') && !spec.endsWith('.mjs')) hygiene.push(`${f}: relative import without .mjs (${spec})`);
    if (!spec.startsWith('.') && !spec.startsWith('node:')) hygiene.push(`${f}: non-builtin import (${spec})`);
  }
}
ok('ESM / no-dep / no-crypto hygiene', hygiene.length === 0, hygiene.join('; '));

console.log(`\nTOTAL: ${pass} passed, ${fail} failed`);
process.exit(fail === 0 ? 0 : 1);

