{
  const parseRepr = (line) => {
    const quote = line[1];
    const body = line.slice(2, -1);
    const out = [];
    for (let i = 0; i < body.length; ) {
      if (body[i] === '\\') {
        const c = body[i + 1];
        if (c === 'x') {
          out.push(parseInt(body.slice(i + 2, i + 4), 16));
          i += 4;
        } else if (c === 'n') { out.push(0x0a); i += 2; }
        else if (c === 't') { out.push(0x09); i += 2; }
        else if (c === 'r') { out.push(0x0d); i += 2; }
        else if (c === '\\') { out.push(0x5c); i += 2; }
        else if (c === quote) { out.push(quote.charCodeAt(0)); i += 2; }
        else throw new Error(`unhandled escape \\${c}`);
      } else {
        out.push(body.charCodeAt(i));
        i += 1;
      }
    }
    return new Uint8Array(out);
  };

  const vectors = JSON.parse(readFileSync('/workspace/harness/vectors.json', 'utf8'));
  let used = 0;
  let bad = 0;
  for (const v of vectors) {
    if (v.code !== 0 || !v.stdout) continue;
    const [l1, l2] = v.stdout.trimEnd().split('\n');
    const k1 = enc(v.key1);
    const k2v = enc(v.key2);
    const d = enc(v.data);
    if (!isValidKeySize(k1.length) || !isValidKeySize(k2v.length) || d.length !== 16) continue;
    used += 1;
    const ct = new AES(k1).encryptBlock(d);
    const wrong = new AES(k2v).decryptBlock(ct);
    if (hex(ct) !== hex(parseRepr(l1))) bad += 1;
    if (hex(wrong) !== hex(parseRepr(l2))) bad += 1;
  }
  ok(`harness vectors.json end-to-end (${used} of ${vectors.length} usable)`, bad === 0 && used > 100, `${bad} mismatches`);
}

